last rawSHA 88e5be54f22eeb99b6a0c289f66b2bc6740fc1901977febe1e2f99952a20c4a1
{
  "questions": [
    {
      "id": "q1260",
      "source_numbers": [
        "1260"
      ],
      "intent": {
        "task": "Find sharp worst-case draw counts, distinguishing interchangeable socks from left/right gloves.",
        "source_solution": "There are two sock colors. Two socks can be one of each color, whereas three force a repeated color, so the minimum sock draw is 3. A glove pair requires one left and one right of the same color. Each color has 10 left and 10 right gloves. A pair-free selection contains at most one handedness of each color, hence at most 10+10=20 gloves. That maximum is attained by all 20 left-hand gloves. Therefore 21 gloves suffice and 20 do not. The minima are independently 3 socks and 21 gloves. The prose requires matching color within each pair, not one shared color across the sock and glove pairs. No figure is present or opened.",
        "unit_reason": "One native multiple task assesses the different pigeonhole models and the glove lower-bound witness, rather than encoding two numerical answers as a combination code.",
        "concept_blocks": [],
        "limitations": [
          "Selecting guarantees and a witness does not certify independently writing the sharpness proofs or physically sorting the items."
        ],
        "figure_observations": []
      },
      "key": {
        "correct": [
          "a",
          "c",
          "e"
        ],
        "rationales": [
          {
            "option_id": "a",
            "truth": "correct",
            "derivation": "Distributing 3 socks between 2 colors leaves a color with at least 2 socks; two differently colored socks show the lower count is insufficient.",
            "misconception": null
          },
          {
            "option_id": "b",
            "truth": "incorrect",
            "derivation": "Three brown left-hand gloves are an allowed draw and contain no wearable pair.",
            "misconception": "Apply the sock calculation ceil(3/2)=2 to gloves, then incorrectly identify two same-color gloves with a left/right pair."
          },
          {
            "option_id": "c",
            "truth": "correct",
            "derivation": "The inventory contains 10 brown left-hand and 10 black left-hand gloves, giving an allowed 20-glove draw with no right-hand glove.",
            "misconception": null
          },
          {
            "option_id": "d",
            "truth": "incorrect",
            "derivation": "A draw of one brown sock and one black sock has no repeated color.",
            "misconception": "Use the number of colors, 2, as the guaranteed draw count instead of adding one beyond the pair-free maximum."
          },
          {
